echo "Update Hyprland Lua entrypoint to load Omarchy bootstrap"

hyprland_config="$HOME/.config/hypr/hyprland.lua"

if [[ -f $hyprland_config ]] && ! grep -Fq '/default/hypr/bootstrap.lua' "$hyprland_config"; then
  tmp=$(mktemp)

  awk '
    BEGIN {
      replaced = 0
    }

    !replaced && $0 == "-- Load user modules from ~/.config and Omarchy defaults from $OMARCHY_PATH." {
      comment = $0
      got_next = getline next_line
      if (got_next > 0 && next_line == "package.path = os.getenv(\"HOME\")") {
        print "-- Omarchy'\''s bootstrap keeps path setup out of this user config."
        print "dofile((os.getenv(\"OMARCHY_PATH\") or \"/usr/share/omarchy\") .. \"/default/hypr/bootstrap.lua\")"
        replaced = 1

        while ((getline line) > 0) {
          if (line ~ /^[[:space:]]*\.\. package\.path$/) {
            break
          }
        }

        next
      }

      print comment
      if (got_next > 0) {
        print next_line
      }
      next
    }

    { print }
  ' "$hyprland_config" >"$tmp"

  mv "$tmp" "$hyprland_config"

echo "Remove the tmux alert hooks and its bar indicator"

tmux_config="$HOME/.config/tmux/tmux.conf"

# Drop only the hooks Omarchy installed, wherever the migrations that wrote
# them left them, and only the blank run around what goes: every other line
# comes through untouched.
if [[ -f $tmux_config ]]; then
  tmp=$(mktemp)

  if awk '
    function flush(count,   i) { for (i = 0; i < count; i++) print "" }

    function keep(line) {
      if (dropped) { if (printed && blanks) print "" }
      else flush(blanks)

      blanks = 0
      dropped = 0
      printed = 1
      print line
    }

    # The heading only belongs to the block when a removed hook follows it.
    /^[[:space:]]*# Alerts$/ && header == "" { header = $0; next }

    /^[[:space:]]*set-hook -g alert-(bell|activity|silence) .*omarchy\.indicators refresh/ ||
    /^[[:space:]]*set-hook -g (after-select-window|client-session-changed|client-focus-(in|out))(\[[0-9]+\])? .*(omarchy-tmux-alert track|omarchy\.indicators refresh)/ {
      header = ""
      dropped = 1
      next
    }

